mapper.update:
update builder.adk_builder_frd
   set state = #{state},
       updated_at = now(),
       completed_at = case when #{state} in ('REVIEW', 'DONE') then coalesce(completed_at, now()) else null end
 where id = #{id}
   and state = #{expected}

mapper.delete:
delete from builder.adk_builder_frd
 where project_id = #{projectId}
   and id = #{id}
   and state not in ('REVIEW', 'DONE')
